113: .roadmap-card li:before{content:'·';position:absolute;left:2px;color:#9eaa8d;font-size:15px;line-height:11px}
114: .roadmap-card li.done:before{content:'✓';color:#9db37b;font-size:9px;line-height:13px}
115: .roadmap-card code{padding:1px 4px;border:1px solid #3b4436;background:#202820;color:#d0c28f;font:8px var(--mono)}
116: .roadmap-tech{grid-column:1/-1}.roadmap-note{margin:12px 0 0;color:#828c7d;font-size:9px;line-height:1.55}.roadmap-note b{color:#c8bb91}
