437:     return [W / 2 + (x - cameraX) * tilePx - tilePx / 2, H / 2 + (y - cameraY) * tilePx - tilePx / 2];
438:   }
439:   function drawGrh(id, x, y, now, animate = true) {
440:     const frameData = resolveGrh(id, now, animate);
441:     if (!frameData || !frameData.image) return;
442:     const { image, def } = frameData, width = def.w * tilePx / 32, height = def.h * tilePx / 32;
443:     ctx.drawImage(image, def.x, def.y, def.w, def.h, x + (tilePx - width) / 2, y + tilePx - height, width, height);
444:   }
445:   function visibleRange(cameraX, cameraY) {
446:     return {
447:       minX: Math.max(0, Math.floor(cameraX - W / tilePx / 2) - 2),
448:       maxX: Math.min(mapData.width - 1, Math.ceil(cameraX + W / tilePx / 2) + 2),
449:       minY: Math.max(0, Math.floor(cameraY - H / tilePx / 2) - 3),
450:       maxY: Math.min(mapData.height - 1, Math.ceil(cameraY + H / tilePx / 2) + 2)
451:     };
452:   }
453:   function drawGround(range, now, cameraX, cameraY) {
454:     for (let y = range.minY; y <= range.maxY; y++) for (let x = range.minX; x <= range.maxX; x++) {
455:       const [sx, sy] = screenTile(x, y, cameraX, cameraY), layers = mapData.tiles[y][x].g;
456:       if (layers[0]) drawGrh(layers[0], sx, sy, now);
457:       if (layers[1]) drawGrh(layers[1], sx, sy, now);
458:     }
459:   }
460:   function drawCharacter(actor, now, cameraX, cameraY) {
461:     if (!actor.alive) return;
462:     const [x, y] = position(actor), [sx, sy] = screenTile(x, y, cameraX, cameraY);
463:     const body = characters.bodies[String(actor.body)], head = characters.heads[String(actor.head)];
464:     if (!body || !head) return;
465:     const facing = HEADINGS[actor.heading], bodyId = body[`Walk${facing}`], headId = head[`Head${facing}`];
466:     if (actor === byId[selected]) {
467:       ctx.fillStyle = 'rgba(230,194,115,.20)'; ctx.beginPath(); ctx.ellipse(sx + tilePx / 2, sy + tilePx * .88, tilePx * .34, tilePx * .12, 0, 0, Math.PI * 2); ctx.fill();
468:       ctx.strokeStyle = 'rgba(245,211,137,.72)'; ctx.lineWidth = 1; ctx.beginPath(); ctx.ellipse(sx + tilePx / 2, sy + tilePx * .88, tilePx * .36, tilePx * .13, 0, 0, Math.PI * 2); ctx.stroke();
469:     }
470:     drawGrh(bodyId, sx, sy, now, true);
471:     drawGrh(headId, sx + (body.HeadOffsetX || 0) * tilePx / 32, sy + (body.HeadOffsetY || 0) * tilePx / 32, now, false);
472:     const labelY = sy + tilePx + 12, label = actor === player ? 'Viajero del Sur' : actor.name;
473:     ctx.save(); ctx.textAlign = 'center'; ctx.font = `600 ${Math.max(8, tilePx * .25)}px DM Sans, sans-serif`;
474:     ctx.fillStyle = actor === player ? '#f5dc9d' : '#f1ead3'; ctx.shadowColor = '#10130e'; ctx.shadowBlur = 4;
475:     ctx.fillText(label, sx + tilePx / 2, labelY, tilePx * 2.8);
476:     ctx.shadowBlur = 0; ctx.fillStyle = 'rgba(13,16,12,.82)'; ctx.fillRect(sx + tilePx * .14, labelY + 3, tilePx * .72, 3);
477:     ctx.fillStyle = actor.hp > 35 ? '#8bb46c' : '#c96152'; ctx.fillRect(sx + tilePx * .14, labelY + 3, tilePx * .72 * actor.hp / actor.maxHp, 3);
478:     if (actor.flash > 0) { ctx.globalCompositeOperation = 'screen'; ctx.fillStyle = `rgba(255,235,180,${actor.flash * 1.5})`; ctx.fillRect(sx, sy - tilePx, tilePx, tilePx * 2); }
479:     ctx.restore();
480:   }
481:   function drawWorldLayer(range, now, cameraX, cameraY) {
482:     const actorsAt = new Map();
483:     for (const actor of fighters) if (actor.alive) {
484:       const [x, y] = position(actor), key = `${Math.floor(y)},${Math.floor(x)}`;
485:       if (!actorsAt.has(key)) actorsAt.set(key, []); actorsAt.get(key).push(actor);
486:     }
487:     for (let y = range.minY; y <= range.maxY; y++) for (let x = range.minX; x <= range.maxX; x++) {
488:       const [sx, sy] = screenTile(x, y, cameraX, cameraY), layers = mapData.tiles[y][x].g;
489:       if (layers[2]) drawGrh(layers[2], sx, sy, now);
490:       for (const actor of actorsAt.get(`${y},${x}`) || []) drawCharacter(actor, now, cameraX, cameraY);
491:     }
492:     for (let y = range.minY; y <= range.maxY; y++) for (let x = range.minX; x <= range.maxX; x++) {
493:       const id = mapData.tiles[y][x].g[3];
494:       if (id) { const [sx, sy] = screenTile(x, y, cameraX, cameraY); drawGrh(id, sx, sy, now); }
495:     }
496:   }
497:   function drawCombatEffects(cameraX, cameraY, now) {
498:     for (const actor of fighters.slice(1)) {
499:       const aim = actor.aim;
500:       if (!aim) continue;
501:       const [sx, sy] = screenTile(aim.x, aim.y, cameraX, cameraY);
502:       const x = sx + tilePx / 2, y = sy + tilePx / 2;
503:       const pulse = .5 + Math.sin(now / 90) * .16;
504:       ctx.save(); ctx.globalAlpha = .72 + pulse * .28;
505:       ctx.strokeStyle = '#ff685b'; ctx.fillStyle = '#ff685b';
506:       ctx.lineWidth = Math.max(2, tilePx * .065); ctx.shadowColor = '#f04438'; ctx.shadowBlur = tilePx * .35;
507:       ctx.beginPath(); ctx.arc(x, y, tilePx * (.28 + pulse * .035), 0, Math.PI * 2); ctx.stroke();
508:       const arm = tilePx * .42, gap = tilePx * .17;
509:       ctx.beginPath();
510:       ctx.moveTo(x - arm, y); ctx.lineTo(x - gap, y); ctx.moveTo(x + gap, y); ctx.lineTo(x + arm, y);
511:       ctx.moveTo(x, y - arm); ctx.lineTo(x, y - gap); ctx.moveTo(x, y + gap); ctx.lineTo(x, y + arm); ctx.stroke();
512:       ctx.shadowBlur = 4; ctx.textAlign = 'center'; ctx.font = `700 ${Math.max(9, tilePx * .27)}px DM Sans, sans-serif`;
513:       ctx.fillStyle = '#fff0d4'; ctx.fillText(`${actor.name.split(' ')[0]} · APUNTANDO`, x, sy - 4);
514:       ctx.restore();
515:     }
516:     for (const effect of spellEffects) {
517:       const progress = effect.age / effect.duration;
518:       const [x0, y0] = screenTile(effect.x, effect.y, cameraX, cameraY);
519:       const [x1, y1] = screenTile(effect.tx, effect.ty, cameraX, cameraY);
520:       const x = x0 + tilePx / 2 + (x1 - x0) * progress;
521:       const y = y0 + tilePx / 2 + (y1 - y0) * progress;
522:       ctx.save(); ctx.globalAlpha = 1 - progress;
523:       ctx.fillStyle = effect.kind === 'heal' ? '#9ee68b' : effect.kind === 'mage' ? '#ff9a54' : effect.kind === 'ranger' ? '#c9e177' : '#f4df9b';
524:       ctx.shadowColor = ctx.fillStyle; ctx.shadowBlur = tilePx * .55;
525:       ctx.beginPath(); ctx.arc(x, y, tilePx * (.1 + progress * .23), 0, Math.PI * 2); ctx.fill();
526:       if (effect.kind !== 'heal') {
527:         ctx.strokeStyle = ctx.fillStyle; ctx.lineWidth = Math.max(2, tilePx * .06);
528:         ctx.beginPath(); ctx.moveTo(x0 + tilePx / 2, y0 + tilePx / 2); ctx.lineTo(x, y); ctx.stroke();
529:       }
530:       ctx.restore();
531:     }
532:     for (const item of floatingTexts) {
533:       const [sx, sy] = screenTile(item.x, item.y, cameraX, cameraY), progress = item.age / 1.05;
534:       ctx.save(); ctx.globalAlpha = Math.min(1, (1 - progress) * 2.5);
535:       ctx.textAlign = 'center'; ctx.font = `800 ${Math.max(14, tilePx * .48)}px DM Sans, sans-serif`;
536:       ctx.fillStyle = item.kind === 'heal' ? '#9fe58e' : item.kind === 'miss' ? '#ffd27a' : '#ff8274'; ctx.shadowColor = '#11150f'; ctx.shadowBlur = 5;
537:       ctx.fillText(item.text, sx + tilePx / 2, sy - tilePx * .18 - progress * tilePx * .8);
538:       ctx.restore();
539:     }
540:   }
541:   function draw() {
542:     ctx.clearRect(0, 0, W, H);
543:     if (!mapData) {
544:       ctx.fillStyle = '#182116'; ctx.fillRect(0, 0, W, H); ctx.fillStyle = '#e5d5a5'; ctx.textAlign = 'center';
545:       ctx.font = '14px DM Sans'; ctx.fillText('Cargando el mundo de Argentum Online…', W / 2, H / 2); return;
546:     }
547:     const [cx, cy] = position(player), now = performance.now();
548:     const range = visibleRange(cx, cy);
549:     ctx.imageSmoothingEnabled = false;
550:     drawGround(range, now, cx, cy); drawWorldLayer(range, now, cx, cy); drawCombatEffects(cx, cy, now);
551:   }
552:   function refreshHud() {
553:     if (!player) return;
554:     $('healthBar').style.width = `${player.hp / player.maxHp * 100}%`;
555:     $('healthValue').textContent = `${Math.ceil(player.hp)} / ${player.maxHp}`;
556:     $('manaBar').style.width = `${player.mana / player.maxMana * 100}%`;
557:     $('manaValue').textContent = `${Math.floor(player.mana)} / ${player.maxMana}`;
558:     document.querySelectorAll('.spell-slot').forEach((button, index) => {
559:       const skill = CLASS_PROFILES[currentClass].skills[index], cooldown = player.skillCooldowns[index];
560:       button.disabled = !player.alive;
561:       button.classList.toggle('unavailable', player.mana < skill.cost);
562:       button.classList.toggle('cooling', cooldown > 0);
563:       button.querySelector('.spell-cost').textContent = cooldown > 0 ? `${cooldown.toFixed(1)}s` : `${skill.cost} maná`;
564:     });
565:     $('playerKills').innerHTML = `${kills} <i>/ 5</i>`; $('rosterPlayerKills').textContent = kills;
566:     $('score-luna').textContent = byId.luna.kills; $('score-bruno').textContent = byId.bruno.kills; $('score-mateo').textContent = byId.mateo.kills;
567:     $('progressText').textContent = `${kills} / 5`; $('progressBar').style.width = `${Math.min(100, kills / 5 * 100)}%`;
568:     $('timer').textContent = `${String(Math.floor(remaining / 60)).padStart(2, '0')}:${String(Math.floor(remaining % 60)).padStart(2, '0')}`;
569:     const target = byId[selected]; $('targetName').textContent = target?.alive ? target.name : 'Sin objetivo';
570:     $('targetStatus').textContent = target?.alive ? `${Math.round(target.hp)}% · ${distance(player, target) <= 1 ? 'AL ALCANCE' : 'FUERA DE ALCANCE'}` : 'Seleccioná un combatiente';
571:     $('attackBtn').disabled = !target?.alive || distance(player, target) > 1 || player.attackCd > 0;
572:     for (const actor of fighters) {
573:       const row = document.querySelector(`[data-fighter="${actor.id}"]`);
574:       if (row) { row.classList.toggle('fighter-dead', !actor.alive); row.classList.toggle('fighter-leading', actor === player && kills >= 3); row.classList.toggle('targeted', actor.id === selected); }
575:     }
576:   }
577:   function endMatch(won) {
578:     if (gameOver) return; gameOver = true;
579:     $('resultPanel').classList.remove('hidden'); $('resultTitle').textContent = won ? 'VICTORIA' : 'FIN DE LA RONDA';
580:     $('resultTitle').style.color = won ? '#e2c47e' : '#c6c7b9';
581:     $('resultSub').textContent = won ? 'El Robledal recuerda tu nombre.' : 'La arena volverá a abrir sus puertas.';
582:   }
583:   function resetGame() {
584:     for (const actor of fighters) Object.assign(actor, { x: actor.homeX, y: actor.homeY, hp: actor === player ? player.maxHp : 100, mana: actor === player ? player.maxMana : 0, alive: true, kills: 0, step: null, stepTime: 0, respawn: 0, flash: 0, attackCd: rand(.2, .8), aiTimer: rand(.2, 1), aim: null, skillCooldowns: [0, 0, 0] });
585:     floatingTexts.length = 0; spellEffects.length = 0;
586:     selected = 'luna'; selectedSkill = null; kills = 0; remaining = 180; elapsed = 0; gameOver = false; paused = false; keys.clear();
587:     refreshSkillSelection();
588:     $('resultPanel').classList.add('hidden'); $('battleLog').innerHTML = '<div class="empty-log">Las hazañas de la arena aparecerán aquí.</div>';
589:     $('killFeed').innerHTML = '<div class="feed-line"><span class="feed-gold">✦</span> <b>La arena te espera</b><span>—</span> buena suerte, viajero.</div>';
590:     refreshHud(); toast('Nueva ronda · elegí un objetivo y luchá.');
591:   }
592:   function togglePause() { paused = !paused; toast(paused ? 'Partida pausada' : 'Partida reanudada'); }
593:   function actorAtPointer(x, y) {
594:     const [cx, cy] = position(player), range = visibleRange(cx, cy); let best = null, bestScore = Infinity;
595:     for (const actor of fighters) {
596:       if (!actor.alive) continue;
597:       const [ax, ay] = position(actor), [sx, sy] = screenTile(ax, ay, cx, cy);
598:       if (x >= sx - 5 && x <= sx + tilePx + 5 && y >= sy - tilePx * 1.2 && y <= sy + tilePx) {
599:         const score = Math.hypot(x - (sx + tilePx / 2), y - (sy + tilePx / 2)); if (score < bestScore) { best = actor; bestScore = score; }
600:       }
601:     }
602:     return best;
603:   }
604:   window.addEventListener('pointerdown', () => { audioReady = true; }, { once: true });
605:   window.addEventListener('keydown', event => {
606:     audioReady = true; const key = event.key.toLowerCase();
607:     if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' '].includes(key)) event.preventDefault();
608:     if (key === 'escape') {
609:       if (!$('helpModal').classList.contains('hidden')) $('helpModal').classList.add('hidden');
610:       else if (!$('sidePanel').classList.contains('hidden')) toggleScoreboard(false);
611:       else togglePause();
612:       return;
613:     }
614:     if (key === 'enter' || key === 'f') { event.preventDefault(); attack(); return; }
615:     if (['1', '2', '3'].includes(key)) { selectSkill(Number(key) - 1); return; }
616:     if (key === 'tab') { event.preventDefault(); const next = fighters.filter(f => f !== player && f.alive); if (next.length) selectTarget(next[(next.findIndex(f => f.id === selected) + 1) % next.length]); return; }
617:     keys.add(key);
618:   });
619:   window.addEventListener('keyup', event => keys.delete(event.key.toLowerCase()));
620:   window.addEventListener('blur', () => { keys.clear(); clearJoystick(); });
621:   canvas.addEventListener('pointerdown', event => {
622:     const rect = canvas.getBoundingClientRect(), target = actorAtPointer(event.clientX - rect.left, event.clientY - rect.top);
623:     if (target) handleCanvasTarget(target);
624:   });
625:   canvas.addEventListener('contextmenu', event => event.preventDefault());
626:   $('attackBtn').addEventListener('click', () => attack());
627:   $('classSelect').addEventListener('change', event => applyClass(event.target.value));
628:   document.querySelectorAll('.spell-slot').forEach(button => button.addEventListener('click', () => selectSkill(Number(button.dataset.skill))));
629:   $('scoreboardToggle').addEventListener('click', () => toggleScoreboard());
630:   document.querySelectorAll('.roster-row[data-fighter]').forEach(row => {
631:     if (row.dataset.fighter !== 'player') row.addEventListener('click', () => selectTarget(byId[row.dataset.fighter]));
632:   });
633:   const joystick = $('joystick');
634:   if (joystick) {
635:     joystick.addEventListener('pointerdown', event => { event.preventDefault(); joystick.setPointerCapture(event.pointerId); updateJoystick(event); });
636:     joystick.addEventListener('pointermove', event => { if (joystick.hasPointerCapture(event.pointerId)) updateJoystick(event); });
637:     joystick.addEventListener('pointerup', clearJoystick);
638:     joystick.addEventListener('pointercancel', clearJoystick);
639:     joystick.addEventListener('lostpointercapture', clearJoystick);
640:   }
641:   $('restartBtn').addEventListener('click', resetGame); $('playAgain').addEventListener('click', resetGame);
642:   $('soundToggle').addEventListener('click', () => { audioOn = !audioOn; $('soundLabel').textContent = `SONIDO ${audioOn ? 'ON' : 'OFF'}`; $('soundIcon').textContent = audioOn ? '♫' : '♪'; });
643:   $('helpBtn').addEventListener('click', () => $('helpModal').classList.remove('hidden'));
644:   $('closeHelp').addEventListener('click', () => $('helpModal').classList.add('hidden'));
645:   $('helpModal').addEventListener('click', event => { if (event.target === $('helpModal')) $('helpModal').classList.add('hidden'); });
646:   $('menuBtn').addEventListener('click', togglePause);
647:   let previous = performance.now();
648:   function loop(now) { const dt = Math.min(.05, (now - previous) / 1000); previous = now; update(dt); draw(); requestAnimationFrame(loop); }
649:   renderSkills(); refreshHud(); loadAssets(); requestAnimationFrame(loop);
650: })();

